pub fn fill_HSD_JObj(p: &mut HSD_JObj) { unsafe {
    p.object.ref_count = fv() as _;
    p.object.ref_count_individual = fv() as _;
    p.next = pick_HSD_JObj();
    p.parent = pick_HSD_JObj();
    p.child = pick_HSD_JObj();
    p.flags = fv() as _;
    for i0 in 0..8 { unsafe { *(&mut p.u as *mut _ as *mut u8).add(i0) = rnd() as u8; } }
    p.rotate.x = rg();
    p.rotate.y = rg();
    p.rotate.z = rg();
    p.rotate.w = rg();
    p.scale.x = rg();
    p.scale.y = rg();
    p.scale.z = rg();
    p.translate.x = rg();
    p.translate.y = rg();
    p.translate.z = rg();
    for i0 in 0..3 {
    for i1 in 0..4 {
    p.mtx[i0][i1] = rg();
    }
    }
    p.id = fv() as _;
} }
pub fn hash_HSD_JObj(p: &HSD_JObj) { unsafe {
    if HDBG { println!("B HSD_JObj"); }
    hm(pi(p.object.parent.class_info));
    hm(p.object.ref_count as u32);
    hm(p.object.ref_count_individual as u32);
    hm(pi(p.next));
    hm(pi(p.parent));
    hm(pi(p.child));
    hm(p.flags as u32);
    for i0 in 0..8 { unsafe { hm(*(&p.u as *const _ as *const u8).add(i0) as u32); } }
    hm(p.rotate.x.to_bits());
    hm(p.rotate.y.to_bits());
    hm(p.rotate.z.to_bits());
    hm(p.rotate.w.to_bits());
    hm(p.scale.x.to_bits());
    hm(p.scale.y.to_bits());
    hm(p.scale.z.to_bits());
    hm(p.translate.x.to_bits());
    hm(p.translate.y.to_bits());
    hm(p.translate.z.to_bits());
    for i0 in 0..3 {
    for i1 in 0..4 {
    hm(p.mtx[i0][i1].to_bits());
    }
    }
    hm(pi(p.scl));
    hm(pi(p.envelopemtx));
    hm(pi(p.aobj));
    hm(pi(p.robj));
    hm(p.id as u32);
} }

pub fn fill_HSD_GObj(p: &mut HSD_GObj) { unsafe {
    p.classifier = fv() as _;
    p.p_link = fv() as _;
    p.gx_link = fv() as _;
    p.p_priority = fv() as _;
    p.render_priority = fv() as _;
    p.obj_kind = fv() as _;
    p.user_data_kind = fv() as _;
    p.next = pick_HSD_GObj();
    p.prev = pick_HSD_GObj();
    p.next_gx = pick_HSD_GObj();
    p.prev_gx = pick_HSD_GObj();
    p.gxlink_prios = fv64() as _;
} }
pub fn hash_HSD_GObj(p: &HSD_GObj) { unsafe {
    if HDBG { println!("B HSD_GObj"); }
    hm(p.classifier as u32);
    hm(p.p_link as u32);
    hm(p.gx_link as u32);
    hm(p.p_priority as u32);
    hm(p.render_priority as u32);
    hm(p.obj_kind as u32);
    hm(p.user_data_kind as u32);
    hm(pi(p.next));
    hm(pi(p.prev));
    hm(pi(p.next_gx));
    hm(pi(p.prev_gx));
    hm(pi(p.proc));
    hm(fi(p.render_cb));
    hm(p.gxlink_prios as u32); hm(((p.gxlink_prios as u64) >> 32) as u32);
    hm(pi(p.hsd_obj));
    hm(pi(p.user_data));
    hm(fi(p.user_data_remove_func));
    hm(pi(p.x34_unk));
} }

